import { mkdirSync, writeFileSync } from "node:fs";
import { pathToFileURL } from "node:url";

import openapiTS, { astToString } from "openapi-typescript";
import ts from "typescript";

// scripts/ -> api-client/ -> packages/ -> repo root/apps/api/openapi.json.
// Resolved via import.meta.url so the CLI writer and the drift test agree
// regardless of cwd.
const SCHEMA_URL = new URL("../../../apps/api/openapi.json", import.meta.url);
const OUT_URL = new URL("../src/generated/schema.d.ts", import.meta.url);

const HEADER = `/**
 * AUTO-GENERATED by \`pnpm openapi\`. DO NOT EDIT BY HAND.
 * Source: apps/api/openapi.json
 */
`;

// `Blob` for every binary body field (the openapi-typescript "binary data"
// recipe). FastAPI emits an uploaded file as OpenAPI 3.1's
// `{"type": "string", "contentMediaType": "application/octet-stream"}`, which the
// generator would otherwise type as `string` — and a `string` field is exactly
// what a caller CANNOT put a browser `File` into, so every upload site would need
// an `as unknown as string` cast that lies about the wire. The transform is the
// documented seam for this; the generated file stays generated (never hand-edited).
const BLOB_NODE = ts.factory.createTypeReferenceNode(
  ts.factory.createIdentifier("Blob"),
);

function binaryToBlob(schemaObject) {
  if (
    schemaObject.format === "binary" ||
    schemaObject.contentMediaType === "application/octet-stream"
  ) {
    return BLOB_NODE;
  }
  return undefined;
}

// Single source of the generated bytes: both the CLI writer (below) and the
// drift test import this, so they cannot disagree.
export async function generateSchema() {
  const ast = await openapiTS(SCHEMA_URL, { transform: binaryToBlob });
  return HEADER + "\n" + astToString(ast);
}

// Script mode: write the file. pathToFileURL avoids the URL-encoding fragility
// of a `file://${process.argv[1]}` template (AM6).
if (import.meta.url === pathToFileURL(process.argv[1]).href) {
  mkdirSync(new URL(".", OUT_URL), { recursive: true });
  writeFileSync(OUT_URL, await generateSchema());
}
